const {execSync}=require("child_process");
const pkg=require("./package.json");
const direct=new Set([...Object.keys(pkg.dependencies||{}),...Object.keys(pkg.devDependencies||{})]);
const diff=execSync("git diff --cached package-lock.json",{encoding:"utf8",maxBuffer:1e8}).split("\n");
let cur=null, changes={};
for(const line of diff){
  const m=line.match(/^@@|^\s*"node_modules\/(.+?)":/);
  const nm=line.match(/^\s*"node_modules\/([^"]+)":/);
  if(nm){cur=nm[1];}
  const v=line.match(/^([+-])\s*"version":\s*"([^"]+)"/);
  if(v&&cur&&direct.has(cur)){ (changes[cur]=changes[cur]||{})[v[1]==="+"?"new":"old"]=v[2]; }
}
const rows=Object.entries(changes).filter(([k,x])=>x.old&&x.new&&x.old!==x.new).sort();
for(const [k,x] of rows) console.log("  "+k.padEnd(32)+x.old+" -> "+x.new);
console.log("  ("+rows.length+" direct deps changed resolved version)");
' 2>&1

